function redactSecrets(content) {
  let redacted = false;
  let result = content;
  const sensitiveNames = [
    "API_KEY",
    "API_TOKEN",
    "ACCESS_TOKEN",
    "AUTH_TOKEN",
    "SECRET",
    "PASSWORD",
    "PRIVATE_KEY",
    "CLIENT_SECRET",
    "CLOUDFLARE_API_TOKEN",
    "GITHUB_TOKEN"
  ];

  for (const name of sensitiveNames) {
    const escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const patterns = [
      new RegExp(
        `(${escapedName}\\s*=\\s*)(["']?)([^"'\\r\\n,;]+)\\2`,
